package com.bplus.share;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.io.*;
public final class Profile {
 public static void init(){if(Store.get("username","").isEmpty())Store.set("username","user_"+java.util.UUID.randomUUID().toString().replace("-","").substring(0,9));if(Store.get("profileName","").isEmpty())Store.set("profileName",Store.deviceName());}
 public static JSONObject local(){init();JSONObject p=new JSONObject();try{p.put("id",Store.get("deviceId",""));p.put("name",Store.get("profileName",Store.deviceName()));p.put("username",Store.get("username",""));p.put("device",Store.deviceName());p.put("photo",Store.get("photo",""));}catch(Exception ignored){}return p;}
 public static JSONObject clean(JSONObject p)throws Exception{JSONObject o=new JSONObject();String id=p.getString("id"),name=p.optString("name"),user=p.optString("username"),photo=p.optString("photo");if(!id.matches("[A-Za-z0-9_-]{1,80}")||name.length()>80||user.length()>40||photo.length()>40000)throw new IOException("Profile too large");o.put("id",id);o.put("name",name);o.put("username",user);o.put("device",p.optString("device","").substring(0,Math.min(80,p.optString("device","").length())));if(!photo.isEmpty()){byte[] bytes=android.util.Base64.decode(photo,0);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(opt.outWidth>256||opt.outHeight>256||opt.outWidth<=0)throw new IOException("Invalid avatar");}o.put("photo",photo);return o;}
 public static ImageView avatar(Activity a,JSONObject p,int size){ImageView v=new ImageView(a);v.setScaleType(ImageView.ScaleType.CENTER_CROP);v.setBackground(Ui.round(Ui.field,size/2,a));v.setClipToOutline(true);v.setImageResource(android.R.drawable.ic_menu_myplaces);try{byte[] b=android.util.Base64.decode(p.optString("photo"),0);Bitmap bitmap=BitmapFactory.decodeByteArray(b,0,b.length);if(bitmap!=null)v.setImageBitmap(bitmap);}catch(Exception ignored){}v.setLayoutParams(Ui.lp(Ui.dp(a,size),Ui.dp(a,size)));return v;}
 public static void savePhoto(Activity a,Uri u)throws Exception{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=a.getContentResolver().openInputStream(u)){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=1;while(o.outWidth/o.inSampleSize>256||o.outHeight/o.inSampleSize>256)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b;try(InputStream in=a.getContentResolver().openInputStream(u)){b=BitmapFactory.decodeStream(in,null,o);}if(b==null)throw new IOException("Unsupported photo");float scale=Math.min(1f,160f/Math.max(b.getWidth(),b.getHeight()));Bitmap small=Bitmap.createScaledBitmap(b,Math.max(1,(int)(b.getWidth()*scale)),Math.max(1,(int)(b.getHeight()*scale)),true);ByteArrayOutputStream out=new ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,75,out);if(out.size()>29000)throw new IOException("Photo too large");Store.set("photo",android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP));}
}
